    </nav>

    <div class="category-list">
        <div class="category-item">
            <img src="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAJAAAACCAYAAACWj2mUAAAAIUlEQVR42mNkYGBgYGBgAAABGgCiwAAAAASUVORK5CYII=" alt="川菜">
            <h3>川菜</h3>
        </div>
        <div class="category-item">
            <img src="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAJAAAACCAYAAACWj2mUAAAAIUlEQVR42mNkYGBgYGBgAAABGgCiwAAAAASUVORK5CYII=" alt="火锅">
            <h3>火锅</h3>
        </div>
        <div class="category-item">
            <img src="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAJAAAACCAYAAACWj2mUAAAAIUlEQVR42mNkYGBgYGBgAAABGgCiwAAAAASUVORK5CYII=" alt="快餐">
            <h3>快餐</h3>
        </div>
        <div class="category-item">
            <img src="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAJAAAACCAYAAACWj2mUAAAAIUlEQVR42mNkYGBgYGBgAAABGgCiwAAAAASUVORK5CYII=" alt="甜点">
            <h3>甜点</h3>
        </div>
